-- Semilla de dev y staging: los partidos de matches.csv (docs/04-datos/datos-ejemplo/), con su
-- estado y su marcador. No se edita a mano: la escribe scripts/datos-ejemplo/semillas.mjs.
-- Es repetible e idempotente: cada partido se inserta solo si su jornada no lo tiene ya.
INSERT INTO matches (matchday_id, home_team_id, away_team_id, venue_id, starts_at, status, home_sets, away_sets, created_at, updated_at)
  SELECT md.id, (SELECT id FROM teams WHERE season_id = (SELECT id FROM seasons WHERE name = '2026-27') AND category_id = (SELECT id FROM categories WHERE name = 'Alevín' AND gender = 'MALE') AND name = 'Los Chicharros V.C.'), (SELECT id FROM teams WHERE season_id = (SELECT id FROM seasons WHERE name = '2026-27') AND category_id = (SELECT id FROM categories WHERE name = 'Alevín' AND gender = 'MALE') AND name = 'Club Voleibol Tabaiba'), (SELECT id FROM venues WHERE name = 'Polideportivo La Marina'), '2026-10-03 08:30:00', 'FINISHED', 3, 2, UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)
  FROM matchdays md JOIN competitions c ON c.id = md.competition_id WHERE c.season_id = (SELECT id FROM seasons WHERE name = '2026-27') AND c.category_id = (SELECT id FROM categories WHERE name = 'Alevín' AND gender = 'MALE') AND c.name = 'Liga Insular Alevín masculina' AND md.number = 1
  AND NOT EXISTS (SELECT 1 FROM matches x WHERE x.matchday_id = md.id AND x.home_team_id = (SELECT id FROM teams WHERE season_id = (SELECT id FROM seasons WHERE name = '2026-27') AND category_id = (SELECT id FROM categories WHERE name = 'Alevín' AND gender = 'MALE') AND name = 'Los Chicharros V.C.') AND x.away_team_id = (SELECT id FROM teams WHERE season_id = (SELECT id FROM seasons WHERE name = '2026-27') AND category_id = (SELECT id FROM categories WHERE name = 'Alevín' AND gender = 'MALE') AND name = 'Club Voleibol Tabaiba'));
